package com.mygo.music;

import android.app.*;
import android.content.*;
import android.graphics.Rect;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;

/** Exercises the shipped playlist screens and inspects what the plugin actually receives. */
final class SourcePlaylistUiChecks {
    static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    static AccessibilityNodeInfo node(Instrumentation test,String text){AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root!=null)for(AccessibilityNodeInfo item:root.findAccessibilityNodeInfosByText(text))if(text.contentEquals(item.getText()))return item;return null;}
    static void click(Instrumentation test,String text)throws Exception{long until=SystemClock.elapsedRealtime()+7000;while(SystemClock.elapsedRealtime()<until){AccessibilityNodeInfo item=node(test,text);if(item!=null&&item.performAction(AccessibilityNodeInfo.ACTION_CLICK))return;SystemClock.sleep(50);}throw new AssertionError("playlist UI missing: "+text+"; current UI: "+uiText(test.getUiAutomation().getRootInActiveWindow()));}
    static String uiText(AccessibilityNodeInfo node){if(node==null)return "none";StringBuilder result=new StringBuilder();if(node.getText()!=null)result.append(node.getText()).append(" | ");for(int i=0;i<node.getChildCount();i++)result.append(uiText(node.getChild(i)));return result.toString();}
    static void longClick(Instrumentation test,String text)throws Exception{AccessibilityNodeInfo item=null;long until=SystemClock.elapsedRealtime()+7000;while(item==null&&SystemClock.elapsedRealtime()<until){item=node(test,text);SystemClock.sleep(50);}check(item!=null,"playlist track row missing");if(item.performAction(AccessibilityNodeInfo.ACTION_LONG_CLICK))return;Rect bounds=new Rect();item.getBoundsInScreen(bounds);long down=SystemClock.uptimeMillis();MotionEvent first=MotionEvent.obtain(down,down,MotionEvent.ACTION_DOWN,bounds.centerX(),bounds.centerY(),0);first.setSource(InputDevice.SOURCE_TOUCHSCREEN);test.getUiAutomation().injectInputEvent(first,true);first.recycle();SystemClock.sleep(700);MotionEvent last=MotionEvent.obtain(down,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,bounds.centerX(),bounds.centerY(),0);last.setSource(InputDevice.SOURCE_TOUCHSCREEN);test.getUiAutomation().injectInputEvent(last,true);last.recycle();}
    static void type(Instrumentation test,String value)throws Exception{long until=SystemClock.elapsedRealtime()+7000;while(SystemClock.elapsedRealtime()<until){AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();ArrayDeque<AccessibilityNodeInfo> nodes=new ArrayDeque<>();if(root!=null)nodes.add(root);while(!nodes.isEmpty()){AccessibilityNodeInfo item=nodes.remove();if("android.widget.EditText".contentEquals(item.getClassName())){Bundle args=new Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);if(item.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args))return;}for(int i=0;i<item.getChildCount();i++){AccessibilityNodeInfo child=item.getChild(i);if(child!=null)nodes.add(child);}}SystemClock.sleep(50);}throw new AssertionError("playlist name input unavailable");}
    static JSONObject awaitCall(Context context,String id,String method)throws Exception{long until=SystemClock.elapsedRealtime()+7000;JSONObject call=new JSONObject();while(SystemClock.elapsedRealtime()<until){String raw=context.getSharedPreferences("plugin_data_"+id,0).getString("lastCall","{}");call=new JSONObject(raw);if(method.equals(call.optString("method")))return call.getJSONObject("args");SystemClock.sleep(50);}throw new AssertionError("playlist export not called: "+method+" "+call);}
    static void awaitRows(Instrumentation test,boolean both)throws Exception{long until=SystemClock.elapsedRealtime()+7000;while(SystemClock.elapsedRealtime()<until){AccessibilityNodeInfo a=node(test,"Track A"),b=node(test,"Track B");if(b!=null){if(!both&&a==null)return;if(both&&a!=null){Rect ar=new Rect(),br=new Rect();a.getBoundsInScreen(ar);b.getBoundsInScreen(br);if(ar.top>br.top)return;}}SystemClock.sleep(50);}throw new AssertionError("playlist rows did not reload after mutation");}
    static void run(Instrumentation test)throws Exception{
        Context context=test.getTargetContext();String id="playlist-ui-protocol";context.getSharedPreferences("plugin_data_"+id,0).edit().clear().commit();Activity activity=test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PluginManager manager=new PluginManager(activity);
        try{byte[] script;try(InputStream in=test.getContext().getAssets().open("playlist-ui-fixture.js")){ByteArrayOutputStream data=new ByteArrayOutputStream();byte[] block=new byte[4096];int n;while((n=in.read(block))!=-1)data.write(block,0,n);script=data.toByteArray();}ByteArrayOutputStream data=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(data)){zip.putNextEntry(new ZipEntry("plugin.json"));zip.write(("{\"id\":\""+id+"\",\"main\":\"index.js\"}").getBytes("UTF-8"));zip.closeEntry();zip.putNextEntry(new ZipEntry("index.js"));zip.write(script);zip.closeEntry();}CountDownLatch installed=new CountDownLatch(1);boolean[] ok={false};manager.installZipStream(new ByteArrayInputStream(data.toByteArray()),(success,raw)->{ok[0]=success;installed.countDown();});check(installed.await(30,TimeUnit.SECONDS)&&ok[0],"playlist UI fixture install failed");PluginManager.PluginInfo source=null;for(PluginManager.PluginInfo candidate:manager.list())if(candidate.id.equals(id))source=candidate;check(source!=null,"playlist fixture not listed");PluginManager.PluginInfo selected=source;String[] error={""};SourcePlaylists screens=new SourcePlaylists(activity,manager,new SourcePlaylists.Listener(){public void error(String message){error[0]=message;}public void play(PluginManager.PluginInfo info,String title,JSONObject track){}public String currentId(String source){return "b";}});
            test.runOnMainSync(()->screens.show(selected));click(test,"Owned · 我的");click(test,"歌单操作");click(test,"重命名歌单");type(test,"Renamed");click(test,"保存");JSONObject renamed=awaitCall(context,id,"renamePlaylist");check(renamed.getString("id").equals("owned")&&renamed.getString("name").equals("Renamed"),"rename parameters lost");click(test,"Renamed · 我的");longClick(test,"Track A");click(test,"下移一首");JSONObject moved=awaitCall(context,id,"movePlaylistTrack");check(moved.getInt("from")==0&&moved.getInt("to")==1,"reorder indices wrong");awaitRows(test,true);longClick(test,"Track A");click(test,"从歌单移除");click(test,"移除");JSONObject removed=awaitCall(context,id,"removeFromPlaylist");check(removed.getJSONArray("trackIds").getString(0).equals("a"),"removed wrong source track");awaitRows(test,false);click(test,"关闭");test.runOnMainSync(()->screens.show(selected));click(test,"新建歌单");type(test,"Created");click(test,"保存");check(awaitCall(context,id,"createPlaylist").getString("name").equals("Created"),"playlist create lost name");click(test,"Created · 我的");click(test,"歌单操作");click(test,"删除歌单");click(test,"删除");check(awaitCall(context,id,"deletePlaylist").getString("id").equals("created"),"playlist delete lost identity");click(test,"Fixed · 我的");click(test,"歌单操作");long until=SystemClock.elapsedRealtime()+3000;while(error[0].isEmpty()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);check(error[0].contains("没有可用"),"fixed playlist exposed forbidden mutation");
        }finally{test.runOnMainSync(()->{manager.close();activity.finish();});PluginArchive.delete(new File(context.getFilesDir(),"plugins/"+id));}
    }
}
